mkdir -p src/sys && cat > build.rs <<'EOF'
//! Defines short, named `cfg` aliases so platform checks read as intent
//! (`#[cfg(apple)]`) rather than as long `any(...)`/`all(...)` expressions.
//!
//! `cfg_aliases` also emits the matching `cargo::rustc-check-cfg` lines, so
//! misspelled aliases are still caught by the `unexpected_cfgs` lint.

use cfg_aliases::cfg_aliases;

fn main() {
    cfg_aliases! {
        // Operating-system groups
        apple: { any(target_os = "macos", target_os = "ios", target_os = "tvos", target_os = "watchos", target_os = "visionos") },
        linux_like: { any(target_os = "linux", target_os = "android") },
        bsd: { any(target_os = "freebsd", target_os = "openbsd", target_os = "netbsd", target_os = "dragonfly") },

        // Backend selection — exactly one of these is active for any target.
        unix_backend: { all(unix, not(target_family = "wasm")) },
        windows_backend: { windows },
        wasm_backend: { target_family = "wasm" },
        fallback_backend: { not(any(unix_backend, windows_backend, wasm_backend)) },
    }
}
EOF
cat > src/sys/mod.rs <<'EOF'
//! Platform backends.
//!
//! Each backend exposes the same set of items; exactly one is compiled in and
//! re-exported here. Adding a platform means adding one file and one branch.

cfg_if::cfg_if! {
    if #[cfg(unix_backend)] {
        mod unix;
        pub use unix::*;
    } else if #[cfg(windows_backend)] {
        mod windows;
        pub use windows::*;
    } else if #[cfg(wasm_backend)] {
        mod wasm;
        pub use wasm::*;
    } else {
        mod fallback;
        pub use fallback::*;
    }
}
EOF
cat > src/sys/unix.rs <<'EOF'
use crate::OsFamily;

pub const LINE_ENDING: &str = "\n";

pub fn os_family() -> OsFamily {
    cfg_if::cfg_if! {
        if #[cfg(apple)] {
            OsFamily::Apple
        } else if #[cfg(linux_like)] {
            OsFamily::Linux
        } else if #[cfg(bsd)] {
            OsFamily::Bsd
        } else {
            OsFamily::OtherUnix
        }
    }
}

pub fn config_dir_env() -> Option<&'static str> {
    cfg_if::cfg_if! {
        if #[cfg(apple)] {
            Some("HOME") // ~/Library/Application Support
        } else {
            Some("XDG_CONFIG_HOME")
        }
    }
}
EOF
cat > src/sys/windows.rs <<'EOF'
use crate::OsFamily;

pub const LINE_ENDING: &str = "\r\n";

pub fn os_family() -> OsFamily {
    OsFamily::Windows
}

pub fn config_dir_env() -> Option<&'static str> {
    Some("APPDATA")
}
EOF
cat > src/sys/wasm.rs <<'EOF'
use crate::OsFamily;

pub const LINE_ENDING: &str = "\n";

pub fn os_family() -> OsFamily {
    OsFamily::Wasm
}

pub fn config_dir_env() -> Option<&'static str> {
    None
}
EOF
cat > src/sys/fallback.rs <<'EOF'
//! Used for targets with no dedicated backend (e.g. bare-metal or exotic OSes).

use crate::OsFamily;

pub const LINE_ENDING: &str = "\n";

pub fn os_family() -> OsFamily {
    OsFamily::Unknown
}

pub fn config_dir_env() -> Option<&'static str> {
    None
}
EOF
cat > src/lib.rs <<'EOF'
//! Cross-platform library skeleton.
//!
//! # Conditional-compilation conventions
//!
//! * **Named aliases** — platform groups such as `apple`, `linux_like` and
//!   `bsd` are defined once in `build.rs`; use them instead of repeating
//!   long `any(target_os = ...)` lists.
//! * **`cfg_if!` for chains** — whenever there are more than two mutually
//!   exclusive branches, use `cfg_if::cfg_if!` so the "else" case is explicit
//!   and no branch can be accidentally left uncovered.
//! * **One backend per file** — platform-specific code lives in `src/sys/`,
//!   and every backend exposes the same items. The public API in this file
//!   stays free of `#[cfg]`.

mod sys;

/// Broad operating-system family of the compilation target.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum OsFamily {
    Linux,
    Apple,
    Bsd,
    OtherUnix,
    Windows,
    Wasm,
    Unknown,
}

/// The native line ending for the target platform.
pub const LINE_ENDING: &str = sys::LINE_ENDING;

/// Returns the OS family this crate was compiled for.
pub fn os_family() -> OsFamily {
    sys::os_family()
}

/// Name of the environment variable conventionally used to locate the
/// user's configuration directory, if the platform has one.
pub fn config_dir_env() -> Option<&'static str> {
    sys::config_dir_env()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn os_family_matches_target() {
        let family = os_family();
        cfg_if::cfg_if! {
            if #[cfg(target_os = "linux")] {
                assert_eq!(family, OsFamily::Linux);
            } else if #[cfg(target_os = "macos")] {
                assert_eq!(family, OsFamily::Apple);
            } else if #[cfg(windows)] {
                assert_eq!(family, OsFamily::Windows);
            } else {
                let _ = family;
            }
        }
    }

    #[test]
    fn line_ending_is_nonempty() {
        assert!(LINE_ENDING.ends_with('\n'));
    }
}
EOF
cargo build 2>&1 | tail -3 && cargo test 2>&1 | grep -E "test result|warning|error" ; cargo clippy --all-targets 2>&1 | tail -2

